sys_transform_script.script:
(function runTransformScript(source, map, log, target /*GlideRecord*/) {
	var operation = source.getValue('operation');

	if (operation === 'create_incident') {
		handleCreateIncident();
	} else if (operation === 'update_incident_status') {
		handleUpdateIncidentStatus();
	} else if (operation === 'update_x_xurre_imr_incident') {
		handleUpdateXurrentIncident();
	} else {
		source.setValue('result_status', 'error');
		source.setValue('result_message', 'Unknown operation: ' + operation);
		source.update();
		error = true;
		errorMessage = 'Unknown operation: ' + operation;
	}

	// The default target insert is suppressed by the companion onBefore script
	// (which sets ignore = true). All record writes are performed manually here,
	// in the onAfter phase, per transform-map best practice for target inserts.

	function handleCreateIncident() {
		if (!source.getValue('short_description') || !source.getValue('x_xurre_imr_incident')
				|| !source.getValue('urgency_sys_id') || !source.getValue('state_sys_id')) {
			setError('Missing required fields: u_short_description, u_x_xurre_imr_incident, u_urgency_sys_id, u_state_sys_id');
			return;
		}

		// Idempotency: if an incident already exists for this Xurrent IMR incident,
		// return it instead of inserting a duplicate (guards retries/replays).
		var dupGR = new GlideRecord('incident');
		dupGR.addQuery('x_xurre_imr_x_xurre_imr_incident', source.getValue('x_xurre_imr_incident'));
		dupGR.setLimit(1);
		dupGR.query();
		if (dupGR.next()) {
			source.setValue('result_sys_id', dupGR.getUniqueValue());
			source.setValue('result_number', dupGR.getValue('number'));
			source.setValue('result_status', 'success');
			source.setValue('result_message', 'Incident already exists for this Xurrent IMR incident');
			source.update();
			return;
		}

		var urgencyGR = new GlideRecord('sys_choice');
		urgencyGR.addQuery('name', 'task');
		urgencyGR.addQuery('element', 'urgency');
		urgencyGR.addQuery('sys_id', source.getValue('urgency_sys_id'));
		urgencyGR.query();
		if (!urgencyGR.next()) {
			setError('Urgency not found with sys_id: ' + source.getValue('urgency_sys_id'));
			return;
		}

		var stateGR = new GlideRecord('sys_choice');
		stateGR.addQuery('name', 'incident');
		stateGR.addQuery('element', 'state');
		stateGR.addQuery('sys_id', source.getValue('state_sys_id'));
		stateGR.query();
		if (!stateGR.next()) {
			setError('State not found with sys_id: ' + source.getValue('state_sys_id'));
			return;
		}

		var snowPriority = null;
		if (source.getValue('snow_priority_sys_id')) {
			var priorityGR = new GlideRecord('sys_choice');
			priorityGR.addQuery('name', 'incident');
			priorityGR.addQuery('element', 'priority');
			priorityGR.addQuery('sys_id', source.getValue('snow_priority_sys_id'));
			priorityGR.query();
			if (priorityGR.next()) {
				snowPriority = priorityGR.getValue('value');
			}
		}

		var entityRecordSysId = null;
		var entityTableName = null;
		var entityTypeSysId = source.getValue('entity_type_sys_id');
		var mappingMode = parseInt(source.getValue('entity_type_mapping_mode'));
		var CUSTOM_MODE = 2, NAME_MATCH_MODE = 1;

		if (entityTypeSysId) {
			var sysDbGR = new GlideRecord('sys_db_object');
			sysDbGR.addQuery('sys_id', entityTypeSysId);
			sysDbGR.query();
			if (!sysDbGR.next()) {
				setError('Entity type not found in sys_db_object: ' + entityTypeSysId);
				return;
			}
			entityTableName = sysDbGR.getValue('name');

			if (mappingMode === CUSTOM_MODE) {
				var recordGR = new GlideRecord(entityTableName);
				if (recordGR.get(source.getValue('entity_record_sys_id'))) {
					entityRecordSysId = recordGR.getUniqueValue();
				} else {
					setError('Entity record not found with sys_id: ' + source.getValue('entity_record_sys_id'));
					return;
				}
			} else if (mappingMode === NAME_MATCH_MODE) {
				var nameMatchGR = new GlideRecord(entityTableName);
				nameMatchGR.addQuery('name', source.getValue('service_name'));
				nameMatchGR.query();
				if (nameMatchGR.next()) {
					entityRecordSysId = nameMatchGR.getUniqueValue();
				} else {
					setError('Entity record not found for service_name: ' + source.getValue('service_name'));
					return;
				}
			}
		}

		var incident = new GlideRecord('incident');
		incident.initialize();
		incident.short_description = source.getValue('short_description');
		incident.description = source.getValue('description');
		incident.x_xurre_imr_originated_from = 'x_xurre_imr';
		incident.x_xurre_imr_x_xurre_imr_incident = source.getValue('x_xurre_imr_incident');
		incident.urgency = urgencyGR.getValue('value');
		incident.state = stateGR.getValue('value');
		if (snowPriority) { incident.priority = snowPriority; }

		if (entityTableName && entityRecordSysId) {
			var dictGR = new GlideRecord('sys_dictionary');
			dictGR.addQuery('name', 'IN', 'incident,task');
			dictGR.addQuery('reference', entityTableName);
			dictGR.query();
			while (dictGR.next()) {
				incident.setValue(dictGR.getValue('element'), entityRecordSysId);
			}
		}

		var mandatoryFieldsJson = source.getValue('mandatory_fields');
		if (mandatoryFieldsJson) {
			var mandatoryFields = JSON.parse(mandatoryFieldsJson);
			for (var field in mandatoryFields) {
				incident.setValue(field, mandatoryFields[field]);
			}
		}

		var sysId = incident.insert();
		source.setValue('result_sys_id', sysId);
		source.setValue('result_number', incident.getValue('number'));
		source.setValue('result_status', 'success');
		source.setValue('result_message', 'Incident created successfully');
		source.update();
	}

	function handleUpdateIncidentStatus() {
		var incidentGR = new GlideRecord('incident');
		if (!incidentGR.get(source.getValue('incident_sys_id'))) {
			setError('Incident not found with sys_id: ' + source.getValue('incident_sys_id'));
			return;
		}

		var choiceGR = new GlideRecord('sys_choice');
		choiceGR.addQuery('name', 'incident');
		choiceGR.addQuery('element', 'state');
		choiceGR.addQuery('sys_id', source.getValue('state_sys_id'));
		choiceGR.query();
		if (!choiceGR.next()) {
			setError('State not found with sys_id: ' + source.getValue('state_sys_id'));
			return;
		}

		var urgencyGR = new GlideRecord('sys_choice');
		urgencyGR.addQuery('name', 'task');
		urgencyGR.addQuery('element', 'urgency');
		urgencyGR.addQuery('sys_id', source.getValue('urgency_sys_id'));
		urgencyGR.query();
		if (!urgencyGR.next()) {
			setError('Urgency not found with sys_id: ' + source.getValue('urgency_sys_id'));
			return;
		}

		if (source.getValue('snow_priority_sys_id')) {
			var priorityGR = new GlideRecord('sys_choice');
			priorityGR.addQuery('sys_id', source.getValue('snow_priority_sys_id'));
			priorityGR.query();
			if (priorityGR.next()) {
				incidentGR.priority = priorityGR.getValue('value');
			}
		}

		var mandatoryFieldsJson = source.getValue('mandatory_fields');
		if (mandatoryFieldsJson) {
			var mandatoryFields = JSON.parse(mandatoryFieldsJson);
			for (var field in mandatoryFields) {
				incidentGR.setValue(field, mandatoryFields[field]);
			}
		}

		incidentGR.setValue('state', choiceGR.getValue('value'));
		incidentGR.setValue('urgency', urgencyGR.getValue('value'));
		incidentGR.update();

		source.setValue('result_sys_id', incidentGR.getUniqueValue());
		source.setValue('result_number', incidentGR.getValue('number'));
		source.setValue('result_status', 'success');
		source.setValue('result_message', 'Incident updated successfully');
		source.update();
	}

	function handleUpdateXurrentIncident() {
		var incidentGR = new GlideRecord('incident');
		incidentGR.addQuery('sys_id', source.getValue('incident_sys_id'));
		incidentGR.query();
		if (!incidentGR.next()) {
			setError('Incident not found with sys_id: ' + source.getValue('incident_sys_id'));
			return;
		}

		incidentGR.x_xurre_imr_x_xurre_imr_incident = source.getValue('x_xurre_imr_incident');
		incidentGR.update();

		source.setValue('result_status', 'success');
		source.setValue('result_message', 'Mapping successful');
		source.update();
	}

	function setError(msg) {
		source.setValue('result_status', 'error');
		source.setValue('result_message', msg);
		source.update();
		error = true;
		errorMessage = msg;
	}

})(source, map, log, target);
